 void EvalSuperEllipse(double t1,double t2,double p1,double p2,XYZ *p)
{
 double tmp;
 double ct1,ct2,st1,st2;

 ct1 = cos(t1);
 ct2 = cos(t2);
 st1 = sin(t1);
 st2 = sin(t2);

 // SIGN function return 1 if input is positive, -1 if it is negative
